interface TicketRepository { long countOpen(); }

class TicketService {
    private final TicketRepository repository;
    TicketService(TicketRepository repository) { this.repository = repository; }
    long openCount() { return repository.countOpen(); }
}

public class Main {
    public static void main(String[] args) {
        var service = new TicketService(() -> 7L);
        System.out.println(service.openCount());
    }
}

